using namespace std;

int main(){

    int n; cin>>n;

    vector<int> arr(n);

    for(int&x:arr) cin>>x;

    int swaps=0;

    for(int i=0;i<n-1;i++){

        int mi=i;

        for(int j=i+1;j<n;j++) if(arr[j]<arr[mi]) mi=j;

        if(mi!=i){swap(arr[i],arr[mi]);swaps++;}

    }

    cout<<swaps<<'\n';

}

